// JavaScript must be written in ECMAScript 5.1.

function main() {
  var mappings = [
    {
      desc: "Option+F to Move Forward Word (Option+Right Arrow)",
      from_key: "f",
      to_key: "right_arrow"
    },
    {
      desc: "Option+B to Move Backward Word (Option+Left Arrow)",
      from_key: "b",
      to_key: "left_arrow"
    },
    {
      desc: "Option+D to Delete Forward Word (Option+Delete Forward)",
      from_key: "d",
      to_key: "delete_forward"
    }
  ];

  var manipulators = [];

  for (var i = 0; i < mappings.length; ++i) {
    var item = mappings[i];

    manipulators.push({
      description: item.desc,
      type: "basic",
      from: {
        key_code: item.from_key,
        modifiers: {
          mandatory: ["left_option"],
          optional: ["any"]
        }
      },
      to: [
        {
          key_code: item.to_key,
          modifiers: ["left_option"]
        }
      ]
    });
  }

  return {
    description: "Option+F/B/D for word boundary navigation and forward deletion",
    manipulators: manipulators
  };
}

main();

