// JavaScript must be written in ECMAScript 5.1.

function main() {
  var VIVALDI = { bundle_identifiers: ["^com\\.vivaldi\\.Vivaldi$"] };
  var DELAY = 120;

  function profileSwitch(number, tabCount) {
    var toEvents = [
      { key_code: "p", modifiers: ["left_command", "left_shift"], halt: true, hold_down_milliseconds: DELAY }
    ];
    for (var i = 0; i < tabCount; i++) {
      toEvents.push({ key_code: "tab", halt: true, hold_down_milliseconds: DELAY });
    }
    toEvents.push({ key_code: "return_or_enter" });

    return {
      description: "Ctrl+" + number + " to switch to Vivaldi profile " + number,
      type: "basic",
      from: {
        key_code: String(number),
        modifiers: {
          mandatory: ["left_control"],
          optional: ["any"]
        }
      },
      to: toEvents,
      conditions: [{ type: "frontmost_application_if", bundle_identifiers: VIVALDI.bundle_identifiers }]
    };
  }

  return {
    description: "Ctrl+1/2 to switch Vivaldi profiles",
    manipulators: [
      profileSwitch(1, 1),
      profileSwitch(2, 4)
    ]
  };
}

main();

